e":"3.9#2","role":"primary","depth":"core"},{"contentCode":"3.10#1","role":"primary","depth":"core"},{"contentCode":"3.10#2","role":"primary","depth":"core"}]},{"code":"C3.06","position":19,"title":"Unit 3 · Lesson 6: Government Responses to Social Movements / Balancing Minority and Majority Rights","note":"Topics 3.11, 3.12 · 4 sub-keywords (4 core, 0 light) · ~110 min","kind":"content","unitCode":"3","estMinutes":110,"lessonTrack":"core","scheduledMinutes":120,"links":[{"contentCode":"3.11","role":"primary","depth":"core"},{"contentCode":"3.12","role":"primary","depth":"core"},{"contentCode":"3.11#1","role":"primary","depth":"core"},{"contentCode":"3.11#2","role":"primary","depth":"core"},{"contentCode":"3.12#1","role":"primary","depth":"core"},{"contentCode":"3.12#2","role":"primary","depth":"core"}]},{"code":"C3.07","position":20,"title":"Unit 3 · Lesson 7: Affirmative Action","note":"Topics 3.13 · 2 sub-keywords (2 core, 0 light) · ~110 min · close with a short mixed MCQ+FRQ set for this unit","kind":"content","unitCode":"3","estMinutes":110,"lessonTrack":"core","scheduledMinutes":120,"links":[{"contentCode":"3.13","role":"primary","depth":"core"},{"contentCode":"3.13#1","role":"primary","depth":"core"},{"contentCode":"3.13#2","role":"primary","depth":"core"}]},{"code":"C4.01","position":21,"title":"Unit 4 · Lesson 1: American Attitudes About Government and Politics / Political Socialization","note":"Topics 4.1, 4.2 · 4 sub-keywords (4 core, 0 light) · ~110 min · warm-up: Unit 3 mixed MCQ+FRQ retrieval","kind":"content","unitCode":"4","estMinutes":110,"lessonTrack":"core","scheduledMinutes":120,"links":[{"contentCode":"3.13","role":"review","depth":"core"},{"contentCode":"4.1","role":"primary","depth":"core"},{"contentCode":"4.2","role":"primary","depth":"core"},{"contentCode":"4.1#1","role":"primary","depth":"core"},{"contentCode":"4.1#2","role":"primary","depth":"core"},{"contentCode":"4.2#1","role":"primary","depth":"core"},{"contentCode":"4.2#2","role":"pri